#!/usr/bin/env bash
# Создаёт метки, этап и стартовые задачи для выбранной лабораторной работы.
# Использование: LAB=1 bash .github/scripts/bootstrap.sh
# Безопасно запускать повторно: если в этапе уже есть задачи, новые не создаются.
set -euo pipefail

REPO="${GITHUB_REPOSITORY:?}"
LAB="${LAB:-1}"

case "$LAB" in
  1) MILESTONE="ЛР1: Инициация"
     MS_DESC="Устав проекта, стейкхолдеры, подход, доска. Укажите срок сдачи в настройках этапа." ;;
  2) MILESTONE="ЛР2: Требования и данные"
     MS_DESC="Требования, бэклог, WBS, DoR/DoD, реестр источников, профилирование и первичный анализ данных." ;;
  3) MILESTONE="ЛР3: Планирование"
     MS_DESC="Оценки, сетевой график и критический путь, календарный план, ресурсы, спринты и Roadmap, бюджет и окупаемость, план коммуникаций, Sprint 1." ;;
  4) MILESTONE="ЛР4: Риски и качество"
     MS_DESC="Реестр рисков, Монте-Карло и дерево решений, правовые риски, план качества, правила репозитория, CI, Sprint 1 и релиз v0.4." ;;
  *) echo "Неизвестный номер ЛР: $LAB"; exit 1 ;;
esac

echo "== Метки =="
mk_label() { gh label create "$1" --color "$2" --description "$3" --force --repo "$REPO" >/dev/null; echo "  $1"; }
mk_label "docs"          "0E8A16" "Документы и тексты"
mk_label "task"          "1D76DB" "Рабочая задача"
mk_label "risk"          "B60205" "Риск проекта"
mk_label "decision"      "5319E7" "Принятое решение (ADR)"
mk_label "priority:high" "D93F0B" "Высокий приоритет"
mk_label "question"      "FBCA04" "Вопрос к команде или заказчику"
mk_label "epic"          "3E4B9E" "Эпик: крупный блок функциональности"
mk_label "story"         "C5DEF5" "Пользовательская история"
mk_label "data"          "006B75" "Поиск, загрузка и качество данных"
mk_label "analysis"      "0052CC" "Пространственный и аналитический расчёт"
mk_label "plan"          "BFD4F2" "Планирование: оценки, сроки, ресурсы, бюджет"
mk_label "status"        "FEF2C0" "Статус-отчёт для спонсора"
mk_label "bug"           "D73A4A" "Ошибка в коде, расчёте или данных"
mk_label "quality"       "C2E0C6" "Качество: тесты, проверки, ревью"
mk_label "ci"            "BFDADC" "Автопроверки и настройки репозитория"

echo "== Этап =="
if gh api "repos/$REPO/milestones?state=all" --jq '.[].title' | grep -qxF "$MILESTONE"; then
  echo "  этап уже существует: $MILESTONE"
else
  gh api "repos/$REPO/milestones" -f title="$MILESTONE" -f description="$MS_DESC" >/dev/null
  echo "  создан: $MILESTONE"
fi

echo "== Задачи =="
existing=$(gh issue list --repo "$REPO" --state all --milestone "$MILESTONE" --limit 1 --json number --jq 'length')
if [ "$existing" != "0" ]; then
  echo "  в этапе «$MILESTONE» уже есть задачи, стартовые не создаём"
  exit 0
fi

mk_issue() {
  local title="$1" label="$2" body="$3"
  gh issue create --repo "$REPO" --title "$title" --label "$label" \
    --milestone "$MILESTONE" --body "$body" >/dev/null
  echo "  $title"
}

